import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Normes des experts suprêmes des plans","description":"","frontmatter":{},"headers":[],"relativePath":"fr/17-位面至高强者标准.md","filePath":"fr/17-位面至高强者标准.md"}'),n={name:"fr/17-位面至高强者标准.md"};function r(l,e,o,d,u,p){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="normes-des-experts-supremes-des-plans" tabindex="-1">Normes des experts suprêmes des plans <a class="header-anchor" href="#normes-des-experts-supremes-des-plans" aria-label="Permalink to &quot;Normes des experts suprêmes des plans&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>17</td></tr><tr><td>Module</td><td>Lois cosmiques et systèmes de culture</td></tr><tr><td>Mots-clés</td><td>Suprême des plans, Normes des experts, Activation à 20%, Niveau de l&#39;Origine, Responsabilité des experts</td></tr></tbody></table><h2 id="i-definition-et-positionnement-des-experts-supremes-des-plans" tabindex="-1">I. Définition et positionnement des experts suprêmes des plans <a class="header-anchor" href="#i-definition-et-positionnement-des-experts-supremes-des-plans" aria-label="Permalink to &quot;I. Définition et positionnement des experts suprêmes des plans&quot;">​</a></h2><p>« Expert suprême des plans » est le titre formel donné par la Civilisation Symbiotique de l&#39;Ancre aux cultivateurs ayant atteint le niveau de puissance cosmique, désignant les cultivateurs de pointe dont la force suffit à soutenir indépendamment la stabilité des lois d&#39;un plan et qui peuvent exercer une influence à l&#39;échelle cosmique. Dans la norme unifiée de division des niveaux, les experts suprêmes des plans correspondent au neuvième niveau « niveau de l&#39;Origine » et au-dessus, le groupe de puissance le plus suprême de Heng Yuan Zhou.</p><p>Être un expert suprême des plans n&#39;est pas simplement un titre de niveau de puissance, mais aussi un positionnement de responsabilité et d&#39;identité. Dans le cadre de la civilisation symbiotique, plus la puissance est grande, plus la responsabilité est grande. Les experts suprêmes des plans ne sont pas seulement des individus qui ont réussi leur culture, mais aussi des gardiens de la civilisation, des mainteneurs des lois et des guides pour ceux qui viennent après. L&#39;objectif central de la « stratégie d&#39;activation à 20% » de la civilisation symbiotique est d&#39;activer, au stade précoce de l&#39;établissement de la civilisation, 20% de tous les êtres vivants pour atteindre le niveau d&#39;expert suprême des plans, posant le fondement de puissance pour l&#39;ascension dimensionnelle globale de l&#39;univers.</p><p>Il convient de noter spécialement que l&#39;« expert suprême des plans » de la civilisation symbiotique est essentiellement différent du « seigneur des plans » de l&#39;ère du prédationisme. Les seigneurs des plans de l&#39;ère du prédationisme asservissaient les plans par la puissance et pillaient les ressources, étant les dirigeants et les pilleurs des plans ; tandis que les experts suprêmes des plans de la civilisation symbiotique gardent les plans par la puissance et servent tous les êtres, étant les gardiens et les serviteurs des plans. Cette différence est une manifestation directe de la philosophie centrale d&#39;antiprédationisme de la civilisation symbiotique au niveau des forts.</p><h2 id="ii-normes-d-evaluation-des-experts-supremes-des-plans" tabindex="-1">II. Normes d&#39;évaluation des experts suprêmes des plans <a class="header-anchor" href="#ii-normes-d-evaluation-des-experts-supremes-des-plans" aria-label="Permalink to &quot;II. Normes d&#39;évaluation des experts suprêmes des plans&quot;">​</a></h2><p>L&#39;évaluation des experts suprêmes des plans adopte le « système d&#39;évaluation à quatre dimensions » ; ce n&#39;est que lorsque les quatre dimensions atteignent toutes les normes que l&#39;on peut être formellement reconnu comme expert suprême des plans :</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Contenu de l&#39;évaluation</th><th>Norme de réussite</th><th>Poids</th></tr></thead><tbody><tr><td>Dimension de puissance</td><td>Niveau, niveau d&#39;énergie, capacité de manipulation des lois</td><td>Atteindre le neuvième niveau de la norme unifiée (niveau de l&#39;Origine), capable de mobiliser indépendamment la puissance de l&#39;Origine</td><td>40%</td></tr><tr><td>Dimension de caractère</td><td>Maturité mentale, adhésion éthique, position antiprédation</td><td>Passer l&#39;examen éthique du Tribunal des Ancres, confirmant l&#39;adhésion aux principes d&#39;antiprédation et à la philosophie symbiotique</td><td>25%</td></tr><tr><td>Dimension de contribution</td><td>Contribution au réseau symbiotique, au développement de la civilisation, à la progression commune des Dix Mille Races</td><td>Valeur de contribution atteignant le niveau des 20% supérieurs de la civilisation, avec au moins un enregistrement de contribution de niveau civilisation</td><td>20%</td></tr><tr><td>Dimension de responsabilité</td><td>Volonté et capacité d&#39;assumer les responsabilités publiques</td><td>Prêt et capable d&#39;assumer des responsabilités publiques au-dessus du niveau des plans (telles que la maintenance des ancres, la garde de la civilisation, etc.)</td><td>15%</td></tr></tbody></table><p>La conception du système d&#39;évaluation à quatre dimensions incarne la philosophie d&#39;évaluation des experts de la civilisation symbiotique consistant à « avoir à la fois la vertu et le talent, la vertu d&#39;abord ». La puissance n&#39;est que le fondement ; le caractère, la contribution et la responsabilité sont des normes tout aussi indispensables. Un cultivateur puissant mais de caractère malveillant, refusant d&#39;assumer ses responsabilités, même s&#39;il atteint le niveau de puissance du niveau de l&#39;Origine, ne sera pas reconnu comme « expert suprême des plans », mais sera classé comme « individu à haut risque » et soumis à une surveillance et à des restrictions correspondantes.</p><h2 id="iii-normes-detaillees-de-la-dimension-de-puissance" tabindex="-1">III. Normes détaillées de la dimension de puissance <a class="header-anchor" href="#iii-normes-detaillees-de-la-dimension-de-puissance" aria-label="Permalink to &quot;III. Normes détaillées de la dimension de puissance&quot;">​</a></h2><p>La dimension de puissance est le fondement de l&#39;évaluation des experts suprêmes des plans ; ses normes détaillées comprennent :</p><h3 id="_3-1-normes-de-niveau" tabindex="-1">3.1 Normes de niveau <a class="header-anchor" href="#_3-1-normes-de-niveau" aria-label="Permalink to &quot;3.1 Normes de niveau&quot;">​</a></h3><ul><li>Doit atteindre le neuvième niveau « niveau de l&#39;Origine » de la norme unifiée, touchant les lois de l&#39;Origine de l&#39;univers</li><li>Capable de mobiliser de manière stable la puissance de l&#39;Origine, plutôt qu&#39;une mobilisation explosive occasionnelle</li><li>Le Dao personnel fusionne profondément avec les lois de l&#39;Origine de l&#39;univers, atteignant l&#39;état « le Dao est l&#39;Origine, l&#39;Origine est le Dao »</li></ul><h3 id="_3-2-normes-d-energie" tabindex="-1">3.2 Normes d&#39;énergie <a class="header-anchor" href="#_3-2-normes-d-energie" aria-label="Permalink to &quot;3.2 Normes d&#39;énergie&quot;">​</a></h3><ul><li>L&#39;énergie de l&#39;Origine stockée dans le corps atteint le « niveau des plans » — c&#39;est-à-dire que l&#39;énergie totale est suffisante pour soutenir le fonctionnement des lois fondamentales d&#39;un plan de taille moyenne</li><li>La pureté de l&#39;énergie atteint plus de 99%, presque exempte d&#39;impuretés</li><li>La vitesse de récupération de l&#39;énergie atteint la « récupération instantanée » — même après une consommation massive en combat, on peut récupérer à pleine capacité en un temps extrêmement court</li></ul><h3 id="_3-3-normes-de-manipulation-des-lois" tabindex="-1">3.3 Normes de manipulation des lois <a class="header-anchor" href="#_3-3-normes-de-manipulation-des-lois" aria-label="Permalink to &quot;3.3 Normes de manipulation des lois&quot;">​</a></h3><ul><li>Capable de mobiliser et de manipuler la puissance des lois à l&#39;échelle cosmique</li><li>Capable de participer au réglage fin et à l&#39;optimisation des lois cosmiques, exerçant une influence substantielle sur le fonctionnement des lois</li><li>Capable d&#39;effectuer indépendamment la traversée et les opérations entre plans sans soutien des ancres</li><li>Capable de créer des mondes complets et des systèmes de lois dans l&#39;Espace d&#39;Isolement (capacité du niveau de Création du Monde)</li></ul><h3 id="_3-4-normes-de-forme-de-vie" tabindex="-1">3.4 Normes de forme de vie <a class="header-anchor" href="#_3-4-normes-de-forme-de-vie" aria-label="Permalink to &quot;3.4 Normes de forme de vie&quot;">​</a></h3><ul><li>La forme de vie achève l&#39;évolution de haute dimension, capable d&#39;exister et de fonctionner simultanément dans le plan matériel, la couche d&#39;énergie et le domaine de conscience</li><li>Quasi-immortalité — les attaques et dommages conventionnels ne peuvent constituer une menace mortelle ; seule une puissance de même niveau ou supérieur peut vraiment lui nuire</li><li>Capable d&#39;ancrer son empreinte de vie dans l&#39;Origine de l&#39;univers, capable de renaître par l&#39;ancrage à l&#39;Origine même si le corps physique est détruit</li></ul><h2 id="iv-normes-detaillees-de-la-dimension-de-caractere" tabindex="-1">IV. Normes détaillées de la dimension de caractère <a class="header-anchor" href="#iv-normes-detaillees-de-la-dimension-de-caractere" aria-label="Permalink to &quot;IV. Normes détaillées de la dimension de caractère&quot;">​</a></h2><p>La dimension de caractère est la partie la plus distinctive de l&#39;évaluation des experts de la civilisation symbiotique, et la différence la plus fondamentale avec l&#39;ère du prédationisme :</p><h3 id="_4-1-position-antipredation" tabindex="-1">4.1 Position antiprédation <a class="header-anchor" href="#_4-1-position-antipredation" aria-label="Permalink to &quot;4.1 Position antiprédation&quot;">​</a></h3><ul><li>Endosser et pratiquer fondamentalement l&#39;antiprédationisme, sans aucun antécédent de culture prédatrice</li><li>Même dans des situations extrêmes, ne jamais choisir l&#39;auto-sauvetage au prix de prédation sur autrui</li><li>Résister et s&#39;opposer activement à toute forme de comportement prédateur, osant dire non aux forces prédatrices</li></ul><h3 id="_4-2-philosophie-symbiotique" tabindex="-1">4.2 Philosophie symbiotique <a class="header-anchor" href="#_4-2-philosophie-symbiotique" aria-label="Permalink to &quot;4.2 Philosophie symbiotique&quot;">​</a></h3><ul><li>Comprendre et endosser profondément la philosophie centrale de la civilisation consistant en « symbiose des Dix Mille Races, ascension dimensionnelle de l&#39;univers »</li><li>Toujours prioriser les intérêts symbiotiques dans la culture personnelle et les affaires publiques</li><li>Participer activement à la construction et à la maintenance du réseau symbiotique, prêt à partager les résultats de culture personnels et les connaissances avec tous les êtres vivants</li></ul><h3 id="_4-3-maturite-mentale" tabindex="-1">4.3 Maturité mentale <a class="header-anchor" href="#_4-3-maturite-mentale" aria-label="Permalink to &quot;4.3 Maturité mentale&quot;">​</a></h3><ul><li>Émotionnellement stable, ne nuira pas à la civilisation et à tous les êtres à cause d&#39;émotions personnelles</li><li>Posséder une vision cosmique grandiose et une vision historique à long terme, ne sacrifiant pas le développement à long terme pour des intérêts à court terme</li><li>Capable de supporter des pressions et des revers énormes, restant rationnel et résolu dans les situations difficiles</li></ul><h3 id="_4-4-examen-ethique" tabindex="-1">4.4 Examen éthique <a class="header-anchor" href="#_4-4-examen-ethique" aria-label="Permalink to &quot;4.4 Examen éthique&quot;">​</a></h3><p>L&#39;évaluation de la dimension de caractère est exécutée par le « Comité d&#39;examen éthique » relevant du Tribunal des Ancres ; les méthodes d&#39;examen comprennent :</p><ul><li>Examen du comportement historique : examiner tous les enregistrements de comportement importants du cultivateur à travers l&#39;histoire</li><li>Balayage profond de la conscience : avec le consentement volontaire du cultivateur, effectuer un balayage profond au niveau de la conscience, confirmant ses véritables pensées intérieures</li><li>Test de stress situationnel : créer des dilemmes moraux extrêmes dans des environnements simulés, observant les choix du cultivateur</li><li>Observation à long terme : pour les candidats controversés, mener une observation et une évaluation sur une période de plusieurs années</li></ul><h2 id="v-normes-detaillees-de-la-dimension-de-contribution" tabindex="-1">V. Normes détaillées de la dimension de contribution <a class="header-anchor" href="#v-normes-detaillees-de-la-dimension-de-contribution" aria-label="Permalink to &quot;V. Normes détaillées de la dimension de contribution&quot;">​</a></h2><p>La dimension de contribution mesure la contribution réelle du cultivateur à la civilisation symbiotique et à la progression commune des Dix Mille Races :</p><h3 id="_5-1-types-de-contribution" tabindex="-1">5.1 Types de contribution <a class="header-anchor" href="#_5-1-types-de-contribution" aria-label="Permalink to &quot;5.1 Types de contribution&quot;">​</a></h3><ul><li><strong>Contribution de culture</strong> : effets exemplaires des percées de niveau, création de nouvelles techniques, innovation des théories de culture</li><li><strong>Contribution de connaissances</strong> : partage public des compréhensions de culture, travaux d&#39;éducation et de formation, résultats de recherche académique</li><li><strong>Contribution technologique</strong> : innovation de la technologie d&#39;ingénierie des lois, optimisation de la technologie du Fruit Multiplicateur, amélioration du matériel des ancres</li><li><strong>Contribution de service</strong> : maintenance des ancres, gouvernance de la civilisation, guidance des mentors, coordination interraciale</li><li><strong>Contribution écologique</strong> : restauration écologique planétaire, amélioration de la circulation énergétique des plans, protection de l&#39;environnement cosmique</li><li><strong>Contribution de garde</strong> : résistance aux menaces externes, protection de la sécurité de la civilisation, sauvetage des vies dans les catastrophes</li></ul><h3 id="_5-2-quantification-de-la-contribution" tabindex="-1">5.2 Quantification de la contribution <a class="header-anchor" href="#_5-2-quantification-de-la-contribution" aria-label="Permalink to &quot;5.2 Quantification de la contribution&quot;">​</a></h3><p>Les valeurs de contribution sont enregistrées et calculées automatiquement par le réseau d&#39;ancres ; différents types de contributions reçoivent différents poids selon leur influence et leur valeur. La norme de contribution pour les experts suprêmes des plans est « la valeur de contribution atteignant le niveau des 20% supérieurs de la civilisation », et il doit y avoir au moins une « contribution de niveau civilisation » — une contribution ayant produit une influence majeure et profonde sur le développement de toute la civilisation.</p><h2 id="vi-normes-detaillees-de-la-dimension-de-responsabilite" tabindex="-1">VI. Normes détaillées de la dimension de responsabilité <a class="header-anchor" href="#vi-normes-detaillees-de-la-dimension-de-responsabilite" aria-label="Permalink to &quot;VI. Normes détaillées de la dimension de responsabilité&quot;">​</a></h2><p>La dimension de responsabilité mesure la volonté et la capacité du cultivateur à assumer des responsabilités publiques :</p><h3 id="_6-1-types-de-responsabilites" tabindex="-1">6.1 Types de responsabilités <a class="header-anchor" href="#_6-1-types-de-responsabilites" aria-label="Permalink to &quot;6.1 Types de responsabilités&quot;">​</a></h3><p>Les responsabilités publiques que les experts suprêmes des plans doivent assumer comprennent :</p><ul><li><strong>Garde des ancres</strong> : être responsable de la garde et de la maintenance d&#39;une ou plusieurs ancres avancées</li><li><strong>Conseiller de la civilisation</strong> : servir de conseiller de plus haut niveau de la civilisation, participant aux décisions sur la direction du développement de la civilisation</li><li><strong>Héritage des mentors</strong> : former et guider la prochaine génération de cultivateurs, en particulier les candidats graines ayant le potentiel d&#39;atteindre les niveaux suprêmes</li><li><strong>Patrouille des plans</strong> : patrouiller régulièrement les plans, surveillant la stabilité des plans et le développement de la civilisation</li><li><strong>Réponse aux crises</strong> : entreprendre les tâches de réponse les plus centrales lorsque la civilisation fait face à des crises majeures (telles que l&#39;effondrement des plans, l&#39;invasion externe, etc.)</li><li><strong>Participation aux lois</strong> : participer au réglage fin et à l&#39;optimisation des lois cosmiques, contribuant à l&#39;ascension dimensionnelle globale de l&#39;univers</li></ul><h3 id="_6-2-modes-d-assomption-des-responsabilites" tabindex="-1">6.2 Modes d&#39;assomption des responsabilités <a class="header-anchor" href="#_6-2-modes-d-assomption-des-responsabilites" aria-label="Permalink to &quot;6.2 Modes d&#39;assomption des responsabilités&quot;">​</a></h3><p>Les experts suprêmes des plans peuvent choisir les types de responsabilités à privilégier selon leurs intérêts et leurs points forts, mais ne peuvent pas refuser complètement d&#39;assumer des responsabilités publiques. La civilisation symbiotique met en œuvre le « système d&#39;obligation des forts » — les cultivateurs atteignant le niveau d&#39;expert suprême des plans ont l&#39;obligation d&#39;utiliser une partie de leur puissance pour les affaires publiques. L&#39;obligation spécifique est d&#39;investir au moins 30% de leur temps et de leur énergie dans les responsabilités publiques chaque année.</p><h2 id="vii-la-strategie-d-activation-a-20" tabindex="-1">VII. La stratégie d&#39;activation à 20% <a class="header-anchor" href="#vii-la-strategie-d-activation-a-20" aria-label="Permalink to &quot;VII. La stratégie d&#39;activation à 20%&quot;">​</a></h2><p>La « stratégie d&#39;activation à 20% » est l&#39;une des stratégies centrales de la Civilisation Symbiotique de l&#39;Ancre à son stade précoce ; son objectif est d&#39;activer, dans la première ère après l&#39;établissement de la civilisation, 20% de tous les êtres vivants pour atteindre le niveau d&#39;expert suprême des plans.</p><h3 id="_7-1-objectifs-strategiques" tabindex="-1">7.1 Objectifs stratégiques <a class="header-anchor" href="#_7-1-objectifs-strategiques" aria-label="Permalink to &quot;7.1 Objectifs stratégiques&quot;">​</a></h3><ul><li>Objectif à court terme (dans les 100 ans suivant l&#39;établissement de la civilisation) : activer 1% de tous les êtres vivants pour atteindre le niveau de l&#39;Origine</li><li>Objectif à moyen terme (dans les 500 ans suivant l&#39;établissement de la civilisation) : activer 10% de tous les êtres vivants pour atteindre le niveau de l&#39;Origine</li><li>Objectif à long terme (dans les 1000 ans suivant l&#39;établissement de la civilisation) : activer 20% de tous les êtres vivants pour atteindre le niveau de l&#39;Origine</li></ul><h3 id="_7-2-soutien-strategique" tabindex="-1">7.2 Soutien stratégique <a class="header-anchor" href="#_7-2-soutien-strategique" aria-label="Permalink to &quot;7.2 Soutien stratégique&quot;">​</a></h3><p>La mise en œuvre de la stratégie d&#39;activation à 20% repose sur les conditions de soutien suivantes :</p><ul><li><strong>Ouverture des Trois Cents Systèmes</strong> : fournir des choix de chemins de culture riches pour tous les êtres vivants</li><li><strong>Vulgarisation de la technologie du Fruit Multiplicateur</strong> : l&#39;amplification centuple de déduction de culture améliore considérablement l&#39;efficacité de la culture</li><li><strong>Système de Contrat Lié à la Production</strong> : fournir un soutien de ressources stable aux cultivateurs</li><li><strong>Système de sécurité Un Chemin pour Chacun</strong> : assurer que chaque vie a des conditions de culture de base</li><li><strong>Réseau de mentors</strong> : les cultivateurs avancés guident les cultivateurs débutants, accélérant la formation des talents</li></ul><h3 id="_7-3-signification-strategique" tabindex="-1">7.3 Signification stratégique <a class="header-anchor" href="#_7-3-signification-strategique" aria-label="Permalink to &quot;7.3 Signification stratégique&quot;">​</a></h3><p>La signification de la stratégie d&#39;activation à 20% ne réside pas seulement dans la formation d&#39;un grand nombre d&#39;experts, mais aussi dans :</p><ul><li>Fournir un fondement de puissance suffisant pour l&#39;ascension dimensionnelle globale de l&#39;univers</li><li>Établir un vaste groupe d&#39;experts, empêchant le monopole de puissance des experts individuels</li><li>Former une atmosphère de civilisation où « les experts émergent en succession », inspirant plus de vies à cultiver avec diligence</li><li>Fournir un large fondement d&#39;experts pour la République des Dix Mille Races, assurant que chaque race a ses propres représentants experts suprêmes</li></ul><h2 id="viii-droits-et-traitements-des-experts-supremes-des-plans" tabindex="-1">VIII. Droits et traitements des experts suprêmes des plans <a class="header-anchor" href="#viii-droits-et-traitements-des-experts-supremes-des-plans" aria-label="Permalink to &quot;VIII. Droits et traitements des experts suprêmes des plans&quot;">​</a></h2><p>En retour de leurs responsabilités, les experts suprêmes des plans jouissent des droits et traitements suivants :</p><ul><li><strong>Priorité des ressources</strong> : jouir de la plus haute priorité dans l&#39;allocation des ressources de culture</li><li><strong>Droit de participation aux lois</strong> : avoir le droit de participer aux décisions sur le réglage fin et l&#39;optimisation des lois cosmiques</li><li><strong>Droit de création d&#39;espaces</strong> : avoir le droit de créer leurs propres espaces ou mondes indépendants</li><li><strong>Droit de décision de la civilisation</strong> : avoir des sièges et des droits de vote dans l&#39;organe de décision le plus élevé de la civilisation</li><li><strong>Droit de passage entre plans</strong> : jouir de droits de libre passage dans tous les plans contrôlés par la civilisation symbiotique</li><li><strong>Honneur et révérence</strong> : recevoir le respect et la révérence de toute la civilisation, leurs exploits étant consignés dans les annales de la civilisation</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les normes des experts suprêmes des plans sont la redéfinition par la Civilisation Symbiotique de l&#39;Ancre du concept de « les forts ». Dans la civilisation symbiotique, les forts ne sont pas des pilleurs, pas des seigneurs, pas des dirigeants au-dessus de tout, mais des gardiens, des serviteurs et des guides. La dimension de puissance est le fondement, la dimension de caractère est l&#39;âme, la dimension de contribution est la valeur, et la dimension de responsabilité est l&#39;engagement — ce n&#39;est que lorsque les quatre dimensions sont unies que l&#39;on est un véritable « expert suprême des plans ». L&#39;objectif de la stratégie d&#39;activation à 20% n&#39;est pas seulement de former 20% d&#39;experts, mais de former 20% de gardiens prêts à assumer la responsabilité de la symbiose des Dix Mille Races et de l&#39;ascension dimensionnelle de l&#39;univers. Lorsque 20% de tous les êtres vivants atteignent le niveau d&#39;expert suprême des plans et pratiquent la philosophie symbiotique, l&#39;ascension dimensionnelle globale de l&#39;univers ne sera plus un rêve lointain.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (Division unifiée des niveaux de culture)</li><li>23-20%激活战略规划 (Plan de la stratégie d&#39;activation à 20%)</li><li>19-修炼伦理与边界 (Éthique et limites de la culture)</li></ul>',61)])])}const v=i(n,[["render",r]]);export{m as __pageData,v as default};
